const httpResponse = $input.first().json;
const config = $('Configuracion Funnels').first().json;

const posts = httpResponse.items || [];
const results = [];

for (const post of posts) {
  const labels = post.labels || [];
  const content = post.content || '';

  // Si ya tiene CTA, saltar
  if (content.includes('<div class="funnel-cta"')) {
    results.push({ json: { id: post.id, title: post.title, skipped: true, reason: 'Ya tiene CTA' } });
    continue;
  }

  // Determinar tipo de funnel según labels
  const isPilar = labels.includes('pilar') || labels.includes('pillar');
  const isCluster = labels.includes('cluster') || labels.some(l => l.includes('cluster'));

  let ctaTitle, ctaDesc, ctaText, ctaUrl, bgGradient;

  if (isPilar) {
    ctaTitle = config.FUNNEL_PILAR_TITULO;
    ctaDesc = config.FUNNEL_PILAR_DESC;
    ctaText = config.FUNNEL_PILAR_CTA;
    ctaUrl = config.FUNNEL_PILAR_URL;
    bgGradient = 'linear-gradient(135deg, #1e3a5f 0%, #2563eb 100%)';
  } else if (isCluster) {
    ctaTitle = config.FUNNEL_CLUSTER_TITULO;
    ctaDesc = config.FUNNEL_CLUSTER_DESC;
    ctaText = config.FUNNEL_CLUSTER_CTA;
    ctaUrl = config.FUNNEL_CLUSTER_URL;
    bgGradient = 'linear-gradient(135deg, #064e3b 0%, #10b981 100%)';
  } else {
    ctaTitle = config.FUNNEL_GENERAL_TITULO;
    ctaDesc = config.FUNNEL_GENERAL_DESC;
    ctaText = config.FUNNEL_GENERAL_CTA;
    ctaUrl = config.FUNNEL_GENERAL_URL;
    bgGradient = 'linear-gradient(135deg, #4c1d95 0%, #7c3aed 100%)';
  }

  const ctaHTML = `
<div class="funnel-cta" style="background:${bgGradient};color:#fff;padding:32px 28px;margin:40px 0;border-radius:12px;text-align:center;font-family:inherit;">
  <h3 style="margin:0 0 12px;font-size:1.4em;font-weight:700;color:#fff;">${ctaTitle}</h3>
  <p style="margin:0 0 24px;font-size:1em;opacity:0.92;line-height:1.6;">${ctaDesc}</p>
  <a href="${ctaUrl}" rel="noopener" style="display:inline-block;background:#fff;color:#1a1a2e;padding:14px 36px;border-radius:50px;font-weight:700;font-size:1.05em;text-decoration:none;transition:transform 0.2s;" onmouseover="this.style.transform='scale(1.05)'" onmouseout="this.style.transform='scale(1)'">${ctaText}</a>
</div>`;

  const newContent = content + ctaHTML;

  results.push({
    json: {
      id: post.id,
      title: post.title,
      BLOG_ID: config.BLOG_ID,
      newContent,
      skipped: false,
      ctaType: isPilar ? 'pilar' : (isCluster ? 'cluster' : 'general'),
      labels
    }
  });
}

return results;

const items = $input.all();
return [{
  json: {
    message: '✅ Funnel CTA Injector completado',
    postsConCTANuevo: items.length,
    timestamp: new Date().toISOString()
  }
}];
